input.command:
# Summarize today's transcripts: user queries + assistant conclusions
for id in 5b01de3c-f9e6-4d65-8d87-8446ca93828d 8880542e-98dc-4e8e-ad55-1062c2ae35d5; do
  f="/Users/mac/.cursor/projects/Users-mac-Desktop-CHcode/agent-transcripts/$id/$id.jsonl"
  echo "===== $id size=$(wc -c < "$f") ====="
  python3 - <<PY
import json
path="$f"
with open(path) as f:
  for i,line in enumerate(f):
    try: o=json.loads(line)
    except: continue
    role=o.get('role') or o.get('type') or ''
    # various schemas
    content=o.get('content') or o.get('message') or o.get('text') or ''
    if isinstance(content,list):
      parts=[]
      for c in content:
        if isinstance(c,dict):
          t=c.get('text') or c.get('content') or ''
          if t: parts.append(str(t)[:500])
        else:
          parts.append(str(c)[:300])
      content='\n'.join(parts)
    elif isinstance(content,dict):
      content=str(content.get('text') or content)[:800]
    else:
      content=str(content)[:800]
    content=content.replace('\n',' ')[:400]
    if not content.strip(): continue
    if role in ('user','assistant','human') or 'user' in str(role).lower() or 'assistant' in str(role).lower() or o.get('type') in ('user','assistant'):
      print(f'[{i}] {role}: {content[:350]}')
    elif i<5:
      print(f'[{i}] keys={list(o.keys())[:8]} role={role} snippet={content[:200]}')
PY
done
